/* @lc app=leetcode id=3387 lang=kotlin */ class Solution { fun bfs(pairs: List<List<String>>, rates: DoubleArray, s: String): Map<String, Double> = pairs.indices.flatMap { i -> listOf(pairs[i][0] to (pairs[i][1] to rates[i]), pairs[i][1] to (pairs[i][0] to 1.0 / rates[i])) }.groupBy({ it.first }, { it.second }).let { g -> HashMap<String, Double>().also { it[s] = 1.0 }.also { d -> generateSequence(listOf(s)) { f -> f.flatMap { u -> g[u].orEmpty().filter { (v, _) -> v !in d }.map { (v, r) -> v.also { d[v] = d[u]!! * r } } }.takeIf { it.isNotEmpty() } }.count() } } fun maxAmount(initialCurrency: String, pairs1: List<List<String>>, rates1: DoubleArray, pairs2: List<List<String>>, rates2: DoubleArray): Double = bfs(pairs1, rates1, initialCurrency).let { a1 -> bfs(pairs2, rates2, initialCurrency).let { a2 -> a1.entries.maxOf { (c, x) -> if (c in a2) x / a2[c]!! else 0.0 } } } }